	}
	if strings.TrimSpace(repoPath) == "" {
		repoPath = protocol.RepoRoot()
	}
	absolute, err := filepath.Abs(repoPath)
	if err != nil {
		return "", err
	}
	digest := sha256.Sum256([]byte(absolute))
	repoKey := hex.EncodeToString(digest[:6])
	return filepath.Join(os.TempDir(), "entire-github-actions", repoKey, "sessions"), nil
}

func (a *Agent) ResolveSessionFile(sessionDir, sessionID string) string {
	return filepath.Join(sessionDir, safeFilename(sessionID)+".json")
}

func (a *Agent) FormatResumeCommand(sessionID string) string {
	return "gh run rerun -- " + shellQuote(sessionID)
}

func shellQuote(value string) string {
	return "'" + strings.ReplaceAll(value, "'", "'\\''") + "'"
}
package githubactions

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/external-agents/agents/entire-agent-github-actions/internal/protocol"
)

const (
	actionRelativePath = ".github/actions/entire-proofgate/action.yml"
	actionMarker       = "# Managed by entire-agent-github-actions."
)

func (a *Agent) ParseHook(hookName string, input []byte) (*protocol.EventJSON, error) {
	input = bytes.TrimSpace(input)
	if len(input) == 0 {
		return nil, nil
	}
	var raw protocol.HookInputJSON
	if err := json.Unmarshal(input, &raw); err != nil {
		return nil, fmt.Errorf("parse GitHub Actions hook input: %w", err)
	}
	raw.SessionID = strings.TrimSpace(raw.SessionID)
	if raw.SessionID == "" {
		return nil, nil
	}
	if raw.Timestamp == "" {
		raw.Timestamp = time.Now().UTC().Format(time.RFC3339)
	}
	if raw.SessionRef == "" {
		dir, err := a.GetSessionDir(protocol.RepoRoot())
		if err != nil {
			return nil, err
		}
		raw.SessionRef = a.ResolveSessionFile(dir, raw.SessionID)
	}

	event := &protocol.EventJSON{
		SessionID:  raw.SessionID,
		SessionRef: raw.SessionRef,
		Timestamp:  raw.Timestamp,
		Model:      rawString(raw.RawData, "model"),
		Metadata:   actionMetadata(raw.RawData),
	}
	switch hookName {
	case HookRunStart:
		event.Type = 1
	case HookTurnStart:
		event.Type = 2
		event.Prompt = raw.UserPrompt
	case HookTurnEnd:
		event.Type = 3
		event.ResponseMessage = rawString(raw.RawData, "response_message")
	case HookRunEnd:
		event.Type = 5
	default:
		return nil, nil
	}
	return event, nil
}

func (a *Agent) InstallHooks(localDev, force bool) (int, error) {
	path := filepath.Join(protocol.RepoRoot(), actionRelativePath)
	existing, err := os.ReadFile(path)
	if err == nil {
		if bytes.Equal(existing, []byte(generatedAction(localDev))) {
			return 0, nil
		}
		if !force && !bytes.Contains(existing, []byte(actionMarker)) {
			return 0, fmt.Errorf("refusing to overwrite unmanaged action %s; rerun with --force", actionRelativePath)
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return 0, fmt.Errorf("read existing action: %w", err)
	}

	if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
		return 0, fmt.Errorf("create action directory: %w", err)
	}
	if err := os.WriteFile(path, []byte(generatedAction(localDev)), 0o600); err != nil {
		return 0, fmt.Errorf("write action: %w", err)
	}
	return 1, nil
}

func (a *Agent) UninstallHooks() error {
	path := filepath.Join(protocol.RepoRoot(), actionRelativePath)
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	if !bytes.Contains(data, []byte(actionMarker)) {
		return nil
	}
	if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	removeEmptyParents(filepath.Dir(path), filepath.Join(protocol.RepoRoot(), ".github"))
	return nil
}

func (a *Agent) AreHooksInstalled() bool {
	data, err := os.ReadFile(filepath.Join(protocol.RepoRoot(), actionRelativePath))
	return err == nil && bytes.Contains(data, []byte(actionMarker))
}

func generatedAction(localDev bool) string {
	binary := "entire-agent-github-actions"
	if localDev {
		binary = filepath.Join(protocol.RepoRoot(), "agents", "entire-agent-github-actions", "entire-agent-github-actions")
	}
	return fmt.Sprintf(`%s
name: Entire ProofGate capture
description: Capture a Claude Code Action execution as an Entire session
inputs:
  mode:
    description: Use begin before the AI action and finish after it
    required: true
  execution_file:
    description: Path from the Claude Code Action execution_file output
    required: false
    default: ""
  session_id:
    description: Stable run-scoped id shared by the begin and finish steps
    required: true
  prompt:
    description: Redacted task prompt recorded for the turn
    required: false
    default: ""
runs:
  using: composite
  steps:
    - name: Begin Entire session
      if: inputs.mode == 'begin'
      shell: bash
      env:
        ENTIRE_SESSION_ID: ${{ inputs.session_id }}
        ENTIRE_TASK_PROMPT: ${{ inputs.prompt }}
      run: |
        %s capture-start \
          --session-id "$ENTIRE_SESSION_ID" \
          --prompt "$ENTIRE_TASK_PROMPT"
    - name: Finish Entire session
      if: inputs.mode == 'finish'
      shell: bash
      env:
        ENTIRE_EXECUTION_FILE: ${{ inputs.execution_file }}
        ENTIRE_SESSION_ID: ${{ inputs.session_id }}
      run: |
        %s capture-finish \
          --execution-file "$ENTIRE_EXECUTION_FILE" \
          --session-id "$ENTIRE_SESSION_ID"
`, actionMarker, binary, binary)
}

func removeEmptyParents(start, stop string) {
	for current := start; current != stop && strings.HasPrefix(current, stop); current = filepath.Dir(current) {
		entries, err := os.ReadDir(current)
		if err != nil || len(entries) != 0 {
			return
		}
		if err := os.Remove(current); err != nil {
			return
		}
	}
}

func rawString(raw map[string]interface{}, key string) string {
	value, _ := raw[key].(string)
	return value
}

func actionMetadata(raw map[string]interface{}) map[string]string {
	metadata := map[string]string{}
	for _, key := range []string{"repository", "run_id", "run_attempt", "sha", "workflow", "job"} {
		value := strings.TrimSpace(rawString(raw, key))
		if value != "" {
			metadata[key] = value
		}
	}
	if len(metadata) == 0 {
		return nil
	}
	return metadata
}
package githubactions

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/external-agents/agents/entire-agent-github-actions/internal/protocol"
)

const maxExecutionFileBytes = 128 << 20

type CaptureResult struct {
	SessionID       string                      `json:"session_id"`
	SessionRef      string                      `json:"session_ref"`
	ModifiedFiles   []string                    `json:"modified_files"`
	HasSummary      bool                        `json:"has_summary"`
	TokenUsage      protocol.TokenUsageResponse `json:"token_usage"`
	LifecycleEvents int                         `json:"lifecycle_events"`
}

func (a *Agent) CaptureStart(sessionID, prompt string) (CaptureResult, error) {
	sessionID = strings.TrimSpace(sessionID)
	if sessionID == "" {
		return CaptureResult{}, errors.New("session-id is required")
	}
	sessionRef, err := a.sessionRef(sessionID)
	if err != nil {
		return CaptureResult{}, err
	}

	if err := a.dispatchLifecycle(HookRunStart, protocol.HookInputJSON{
		HookType:   HookRunStart,
		SessionID:  sessionID,
		SessionRef: sessionRef,
		Timestamp:  time.Now().UTC().Format(time.RFC3339),
		RawData:    githubMetadata(),
	}); err != nil {
		return CaptureResult{}, err
	}
	if err := a.dispatchLifecycle(HookTurnStart, protocol.HookInputJSON{
		HookType:   HookTurnStart,
		SessionID:  sessionID,
		SessionRef: sessionRef,
		Timestamp:  time.Now().UTC().Format(time.RFC3339),
		UserPrompt: prompt,
		RawData:    githubMetadata(),
	}); err != nil {
		return CaptureResult{}, err
	}

	return CaptureResult{
		SessionID:       sessionID,
		SessionRef:      sessionRef,
		ModifiedFiles:   []string{},
		LifecycleEvents: 2,
	}, nil
}

func (a *Agent) CaptureFinish(executionFile, sessionID string) (CaptureResult, error) {
	executionFile = strings.TrimSpace(executionFile)
	sessionID = strings.TrimSpace(sessionID)
	if executionFile == "" {
		return CaptureResult{}, errors.New("execution-file is required")
	}
	if sessionID == "" {
		return CaptureResult{}, errors.New("session-id is required")
	}
	info, err := os.Stat(executionFile)
	if err != nil {
		return CaptureResult{}, fmt.Errorf("inspect execution file: %w", err)
	}
	if !info.Mode().IsRegular() {
		return CaptureResult{}, errors.New("execution-file must be a regular file")
	}
	if info.Size() > maxExecutionFileBytes {
		return CaptureResult{}, fmt.Errorf("execution-file exceeds %d bytes", maxExecutionFileBytes)
	}
	data, err := os.ReadFile(executionFile)
	if err != nil {
		return CaptureResult{}, fmt.Errorf("read execution file: %w", err)
	}
	if _, err := parseSDKMessages(data); err != nil {
		return CaptureResult{}, err
	}

	sessionRef, err := a.sessionRef(sessionID)
	if err != nil {
		return CaptureResult{}, err
	}
	if err := a.WriteSession(protocol.AgentSessionJSON{
		SessionID:  sessionID,
		AgentName:  agentName,
		RepoPath:   protocol.RepoRoot(),
		SessionRef: sessionRef,
		NativeData: data,
	}); err != nil {
		return CaptureResult{}, err
	}

	files, _, err := a.ExtractModifiedFiles(sessionRef, 0)
	if err != nil {
		return CaptureResult{}, err
	}
	summary, hasSummary, err := a.ExtractSummary(sessionRef)
	if err != nil {
		return CaptureResult{}, err
	}
	usage, err := a.CalculateTokens(data, 0)
	if err != nil {
		return CaptureResult{}, err
	}
	metadata := githubMetadata()
	if model := executionModel(data); model != "" {
		metadata["model"] = model
	}

	if err := a.dispatchLifecycle(HookTurnEnd, protocol.HookInputJSON{
		HookType:   HookTurnEnd,
		SessionID:  sessionID,
		SessionRef: sessionRef,
		Timestamp:  time.Now().UTC().Format(time.RFC3339),
		RawData:    mergeMetadata(metadata, map[string]interface{}{"response_message": summary}),
	}); err != nil {
		return CaptureResult{}, err
	}
	if err := a.dispatchLifecycle(HookRunEnd, protocol.HookInputJSON{
		HookType:   HookRunEnd,
		SessionID:  sessionID,
		SessionRef: sessionRef,
		Timestamp:  time.Now().UTC().Format(time.RFC3339),
		RawData:    metadata,
	}); err != nil {
		return CaptureResult{}, err
	}

	return CaptureResult{
		SessionID:       sessionID,
		SessionRef:      sessionRef,
		ModifiedFiles:   files,
		HasSummary:      hasSummary,
		TokenUsage:      usage,
		LifecycleEvents: 2,
	}, nil
}

func (a *Agent) sessionRef(sessionID string) (string, error) {
	dir, err := a.GetSessionDir(protocol.RepoRoot())
	if err != nil {
		return "", err
	}
	return a.ResolveSessionFile(dir, sessionID), nil
}

func (a *Agent) dispatchLifecycle(hook string, input protocol.HookInputJSON) error {
	payload, err := json.Marshal(input)
	if err != nil {
		return err
	}
	binary := strings.TrimSpace(os.Getenv("ENTIRE_CLI_PATH"))
	if binary == "" {
		binary = "entire"
	}
	cmd := exec.Command(binary, "hooks", agentName, hook)
	cmd.Dir = protocol.RepoRoot()
	cmd.Env = os.Environ()
	cmd.Stdin = bytes.NewReader(payload)
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		message := strings.TrimSpace(stderr.String())
		if message != "" {
			return fmt.Errorf("Entire %s hook failed: %w: %s", hook, err, message)
		}
		return fmt.Errorf("Entire %s hook failed: %w", hook, err)
	}
	return nil
}

func githubMetadata() map[string]interface{} {
	metadata := map[string]interface{}{}
	for key, envName := range map[string]string{
		"repository":  "GITHUB_REPOSITORY",
		"run_id":      "GITHUB_RUN_ID",
		"run_attempt": "GITHUB_RUN_ATTEMPT",
		"sha":         "GITHUB_SHA",
		"workflow":    "GITHUB_WORKFLOW",
		"job":         "GITHUB_JOB",
	} {
		if value := strings.TrimSpace(os.Getenv(envName)); value != "" {
			metadata[key] = value
		}
	}
	return metadata
}

func mergeMetadata(base map[string]interface{}, extra map[string]interface{}) map[string]interface{} {
	merged := make(map[string]interface{}, len(base)+len(extra))
	for key, value := range base {
		merged[key] = value
	}
	for key, value := range extra {
		merged[key] = value
	}
	return merged
}

func executionModel(data []byte) string {
	messages, err := parseSDKMessages(data)
	if err != nil {
		return ""
	}
	for _, message := range messages {
		if model := strings.TrimSpace(stringValue(message["model"])); model != "" {
			return model
		}
		if nested, ok := asMap(message["message"]); ok {
			if model := strings.TrimSpace(stringValue(nested["model"])); model != "" {
				return model
			}
		}
	}
	return ""
}

func ResolveExecutionFile(path string) (string, error) {
	resolved, err := filepath.Abs(path)
	if err != nil {
		return "", err
	}
	return resolved, nil
}

